import {categories, creators, seeds, matches, webUrl} from './catalog.js';
import {icon} from './icons.js';
const main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem('appshare-v1-'+key))??fallback;}catch{return fallback;}}
function save(key,data){localStorage.setItem('appshare-v1-'+key,JSON.stringify(data));}
const apps=()=>[...seeds,...read('submissions',[])];
const people=()=>[...creators,...read('profiles',[])];
const user=()=>people().find(p=>p.id===read('session',''));
const cat=id=>categories.find(c=>c.id===id);
const author=id=>people().find(p=>p.id===id);
const btn=(href,label,cls='darkbtn',attrs='')=>`<a class="btn ${cls}" href="${esc(href)}" ${attrs}>${label}</a>`;
const link=(route,label)=>`<a class="textlink" href="#/${route}">${esc(label)}</a>`;
const profileName=a=>author(a.author)?.name??'Community creator';
const external='target="_blank" rel="noopener noreferrer"';
const routes=[['','Discover'],['apps','Apps'],['creators','Creators'],['community','Community'],['about','About']];
function header(route){document.querySelector('header').innerHTML=`<div class="nav"><a class="wordmark" href="#/"><img src="assets/mark.svg" alt="">AppShare</a><nav aria-label="Main navigation" id="navlinks">${routes.map(([p,n])=>`<a href="#/${p}" ${route===p?'class="active" aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="actions"><a class="pill circle" href="#/search" aria-label="Search apps">${icon('search')}</a><a class="pill" href="#/login">${user()?'Account':'Log in'}</a><a class="pill upload" href="#/publish">Upload App</a><button class="pill circle mobile" aria-label="Navigation menu" aria-expanded="false" aria-controls="navlinks" style="color:inherit" id="menu">${icon('menu')}</button></div></div>`;
document.querySelector('#menu').onclick=e=>e.currentTarget.setAttribute('aria-expanded',document.querySelector('#navlinks').classList.toggle('open'));}
function cards(items,all=false){return `<div class="grid">${items.map(c=>`<a class="category" style="--art:url(assets/${c.id}.jpg)" href="#/${c.id==='more'?(all?'apps':'categories'):'category/'+c.id}"><span class="cat-icon">${icon(c.icon)}</span><strong>${c.name}</strong><small>${c.sub}</small><span class="round">${icon('arrow')}</span></a>`).join('')}</div>`;}
function home(){return `<section class="hero"><div class="hero-inner"><p class="eyebrow">CREATE · SHARE · EXPLORE</p><h1>Build together.<span>Share your apps with the world.</span></h1><p class="intro">A curated platform for AI-created tools, apps, and creative software.</p><div class="cta">${btn('#/categories','Explore Categories '+icon('arrow'),'white')}${btn('#/how',icon('play')+' How It Works','ghost')}</div></div><svg class="waves" viewBox="0 0 1200 110" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="wave" x1="0" x2="0" y2="1"><stop stop-color="#dae1ff" stop-opacity=".52"/><stop offset="1" stop-color="#6c84ba"/></linearGradient></defs><path d="M0 12C265 83 310 149 610 92S1000 62 1200 87V110H0Z" fill="url(#wave)" stroke="#e0e9ff66"/><path d="M0 74C320 138 575 121 800 87S1050 4 1200 22V110H0Z" fill="url(#wave)" stroke="#e0e9ff66"/></svg></section><section class="browse"><div class="browse-inner"><div class="sectionline"><h2>Browse by Category</h2><a href="#/categories">View All Categories ${icon('arrow')}</a></div>${cards(categories)}</div></section>`;}
function page(title,lead,content,parent=['','Discover']){document.title=title+' · AppShare';return `<div class="shell"><a class="back" href="#/${parent[0]}">← ${esc(parent[1])}</a><h1>${esc(title)}</h1>${lead?`<p class="lead">${esc(lead)}</p>`:''}${content}</div>`;}
function listings(items){return items.length?`<div class="list">${items.map(a=>`<a class="listing" href="#/app/${esc(a.id)}"><span class="meta">${esc(cat(a.category)?.name)} · ${a.demo?'Demo':'Local submission'}</span><h2>${esc(a.name)}</h2><p>${esc(a.description)}</p><small class="muted">By ${esc(profileName(a))}</small></a>`).join('')}</div>`:'<p class="panel">No apps match. Try another name or category.</p>';}
function directory(id,search){const c=cat(id);return page(c?.name??(search?'Search AppShare':'Explore apps'),c?.sub??'Discover tools by name, purpose, or category.',`<label for="query">Search apps</label><br><input id="query" class="searchbox" type="search" placeholder="Search apps and tools…" maxlength="160"><div class="filters"><a href="#/apps" class="${c?'':'active'}">All apps</a>${categories.slice(0,-1).map(t=>`<a class="${t.id===id?'active':''}" href="#/category/${t.id}">${t.name}</a>`).join('')}</div><div id="results" aria-live="polite">${listings(apps().filter(a=>!c||a.category===id))}</div>`,['categories','Categories']);}
function detail(a){const isSeed=seeds.includes(a), tryLink=isSeed?a.tryUrl:webUrl(a.tryUrl), source=isSeed?a.source:webUrl(a.source,true);
return page(a.name,a.description,`<section class="panel"><div class="meta">${esc(cat(a.category)?.name)} · ${a.demo?'Demo listing':'Local submission · Pending review'}</div><p>Created by ${link('creator/'+a.author,profileName(a))}</p>${a.origin?`<p>Remixed from ${link('app/'+a.origin,'the original listing')}.</p>`:''}<div class="links">${tryLink?btn(tryLink,'Try '+icon('arrow'),'darkbtn',isSeed?'':external):''}${source?btn(source,'Source','lightbtn',isSeed?'download="spectrum.html"':external):''}${a.remix&&source&&a.license?(isSeed?btn('#/publish?from='+a.id,'Remix','lightbtn'):btn(source.replace(/\/?$/,'/fork'),'Remix','lightbtn',external)):''}</div><p class="muted">${source?'License · '+esc(a.license||'See repository terms'):'The creator has shared a catalog description.'}</p></section>`,['category/'+a.category,cat(a.category)?.name??'Apps']);}
function login(){const me=user();if(me)return page('Your account',me.name,`<div class="panel"><p>This demo profile is saved in this browser.</p><div class="links">${btn('#/creator/'+me.id,'View profile')}${btn('#/publish','Upload App','lightbtn')}<button id="logout" class="btn lightbtn">Log out</button></div></div>`);
return page('Log in','Choose a display name to use a local demo profile.',`<form class="form panel" id="login"><label>Display name<input name="name" required maxlength="40" autocomplete="nickname"></label><p class="muted">This preview stores profiles on this device. Using an existing display name reopens that demo profile.</p><button class="btn darkbtn">Continue in demo</button><p class="error" role="alert"></p></form>`);}
function publishing(from){if(!user())return page('Upload an app','Start with a local creator profile so your submission has an author.',btn('#/login?next='+encodeURIComponent('publish'+(from?'?from='+from:'')),'Create or open demo profile'));
const starter=from==='spectrum'?seeds[0]:null;
return page(starter?'Remix Spectrum':'Upload an app','Share a hosted app or a GitHub repository for review.',`<form id="publish" class="form panel">${starter?`<p>Download the ${'<a href="examples/spectrum.html" download>MIT-licensed starter</a>'}, edit it, then link your version. Attribution is included in the listing.</p>`:''}<label>App name<input required name="name" maxlength="70" value="${starter?'Spectrum remix':''}"></label><label>Category<select name="category">${categories.slice(0,-1).map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label>Short description<textarea name="description" maxlength="300" required></textarea></label><label>Hosted app URL<input name="tryUrl" type="url" placeholder="https://"></label><label>GitHub repository<input name="source" type="url" placeholder="https://github.com/creator/project"></label><label>Repository license<select name="license"><option value="">See repository terms</option><option>MIT</option><option>Apache-2.0</option><option>GPL-3.0</option><option>BSD-3-Clause</option></select></label><label class="check"><input type="checkbox" name="remix">Allow remixing under the selected license</label><label class="check"><input type="checkbox" required>I have the rights to share this app and its links.</label><p class="muted">Submissions stay in this browser pending review. Binary packages are closed during this preview.</p><button class="btn darkbtn">Submit for review</button><p role="alert" class="error"></p></form>`);}
const how=()=>page('How it works','Find a tool, meet its creator, and build on shared work.',`<ol class="panel about-steps"><li><b>Discover by category.</b> Explore tools made with AI and read what each one does.</li><li><b>Try an app.</b> Open the working demo or hosted app when its creator supplies a link.</li><li><b>Share your work.</b> Submit a link, describe your app, and choose whether others can remix it.</li></ol>${btn('#/categories','Explore Categories')}`);
function trial(id){if(id==='spectrum')return page('Try Spectrum','Select a swatch to copy its hex value.',`<div class="panel links">${['#A2D2FF','#BDB2FF','#FFC6A5','#A6E4D0','#FF99AB'].map(c=>`<button class="btn" data-color="${c}" style="background:${c};color:#1b2843">${c}</button>`).join('')}</div><p role="status" id="status"></p>`,['app/spectrum','Spectrum']);if(id==='indent')return page('Try Indent','Paste JSON to format it on your device.','<form class="form panel" id="indent"><label>JSON<textarea required name="json">{"hello":"world"}</textarea></label><button class="btn darkbtn">Format JSON</button><p role="status" id="status"></p></form>',['app/indent','Indent']);if(id==='pairs')return page('Try Color Pairs','Reveal two tiles at a time to find four matching pairs.','<div class="panel"><div class="memory-grid" id="tiles"></div><p id="status" role="status"></p><button class="btn lightbtn" id="restart">New game</button></div>',['app/pairs','Color Pairs']);return missing();}
const missing=()=>page('Page unavailable','This link does not point to an available listing.',btn('#/apps','Browse apps'));
function render(){const [path,q='']=location.hash.slice(1).split('?');const [route='',id]=(path||'/').replace(/^\//,'').split('/');const params=new URLSearchParams(q);const from=params.get('from');document.body.classList.toggle('home',!route);header(route);document.title='Discover · AppShare';
switch(route){
case '':main.innerHTML=home();break;
case 'categories':main.innerHTML=page('All categories','Choose a collection to explore its apps.',cards(categories.slice(0,-1))+ '<div class="links">'+btn('#/apps','Browse all apps','lightbtn')+'</div>');break;
case 'category':case 'apps':case 'search':main.innerHTML=route==='category'&&(!cat(id)||id==='more')?missing():directory(route==='category'?id:null,route==='search');break;
case 'app':{const a=apps().find(a=>a.id===id);main.innerHTML=a?detail(a):missing();break;}
case 'creators':main.innerHTML=page('Creators','The people behind the apps.',`<div class="list">${people().map(p=>`<a class="listing" href="#/creator/${esc(p.id)}"><h2>${esc(p.name)}</h2><p>${esc(p.bio)}</p></a>`).join('')}</div>`);break;
case 'creator':{const p=author(id);main.innerHTML=p?page(p.name,p.bio,'<h2>Apps by this creator</h2>'+listings(apps().filter(a=>a.author===id)),['creators','Creators']):missing();break;}
case 'how':main.innerHTML=how();break;
case 'community':main.innerHTML=page('Community','Meet the makers and share something you built.',`<div class="panel"><h2>Build on shared work</h2><p>Credit the original creator, follow the repository license, and enable remixing when you want others to build on your app.</p><div class="links">${btn('#/creators','Meet the creators')}${btn('#/publish','Share an app','lightbtn')}</div></div>`);break;
case 'about':main.innerHTML=page('About AppShare','A curated platform for AI-created tools, apps, and creative software.',`<div class="panel"><h2>Build together.</h2><p>AppShare helps people find what someone has already built, try it, and build on it when the creator gives permission.</p><p>This early preview includes sample listings and working browser demos. Profiles and submissions are stored locally.</p>${link('how','How it works')}</div>`);break;
case 'login':main.innerHTML=login();break;case 'publish':main.innerHTML=publishing(from);break;case 'try':main.innerHTML=trial(id);break;default:main.innerHTML=missing();}
bind(route,id,params);window.scrollTo({top:0,behavior:'instant'});if(route==='search')document.querySelector('#query')?.focus();else main.focus({preventScroll:true});}
function bind(route,id,params){const el=s=>document.querySelector(s);
if(el('#query'))el('#query').oninput=e=>el('#results').innerHTML=listings(apps().filter(a=>(route!=='category'||a.category===id)&&matches(a,e.target.value)));
if(el('#logout'))el('#logout').onclick=()=>{save('session','');render();};
if(el('#login'))el('#login').onsubmit=e=>{e.preventDefault();const f=e.target,n=f.elements.name.value.trim();if(!n){f.querySelector('.error').textContent='Enter a display name.';return;}
try{const profiles=read('profiles',[]);let p=profiles.find(p=>p.name.toLowerCase()===n.toLowerCase());if(!p){p={id:crypto.randomUUID(),name:n,bio:'Local demo creator.'};save('profiles',[...profiles,p]);}save('session',p.id);const next=params.get('next');location.hash=next&&/^publish(\?from=spectrum)?$/.test(next)?'/'+next:'/creator/'+p.id;}catch{f.querySelector('.error').textContent='This browser could not save your profile.';}};
if(el('#publish'))el('#publish').onsubmit=e=>{e.preventDefault();const f=e.target,d=new FormData(f),val=k=>String(d.get(k)||'').trim(),err=t=>f.querySelector('.error').textContent=t;
const url=webUrl(val('tryUrl')),source=webUrl(val('source'),true),remix=d.has('remix'),license=val('license');
if(!val('name')||!val('description'))return err('Enter a name and description.');
if((val('tryUrl')&&!url)||(val('source')&&!source))return err('Use an HTTPS app URL and a GitHub repository URL in owner/project format.');
if(!url&&!source)return err('Add a hosted app or GitHub repository.');
if(remix&&(!source||!license))return err('Remixing requires a repository and its license.');
if(!user())return err('Reopen your demo profile to submit.');
const a={id:crypto.randomUUID(),name:val('name'),description:val('description'),category:val('category'),author:user().id,tryUrl:url,source,license,remix,origin:params.get('from')==='spectrum'?'spectrum':''};try{save('submissions',[...read('submissions',[]),a]);location.hash='/app/'+a.id;}catch{return err('This browser could not save your submission.');}};
for(const b of document.querySelectorAll('[data-color]'))b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.color);el('#status').textContent='Copied '+b.dataset.color;}catch{el('#status').textContent='Hex value: '+b.dataset.color;}};
if(el('#indent'))el('#indent').onsubmit=e=>{e.preventDefault();const field=e.target.elements.json;try{field.value=JSON.stringify(JSON.parse(field.value),null,2);el('#status').textContent='Formatted.';}catch{el('#status').textContent='Invalid JSON. Check the quotes, commas, and brackets.';}};
if(el('#tiles')){el('#restart').onclick=()=>render();const deck=['Sky','Rose','Mint','Gold','Sky','Rose','Mint','Gold'];for(let i=7;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}const board=el('#tiles'),status=el('#status');let open=[],solved=0;deck.forEach((color,i)=>{const b=document.createElement('button');const hide=()=>{b.textContent='Tile '+(i+1);};hide();board.append(b);b.onclick=()=>{if(open.length===2||open.includes(b))return;b.textContent=color;open.push(b);if(open.length===2){const [first,second]=open;if(first.textContent===second.textContent){first.disabled=second.disabled=true;open=[];solved++;status.textContent=solved===4?'All four pairs found!':'Pair found.';}else{status.textContent='Try another pair.';setTimeout(()=>{for(const tile of open)tile.textContent='Tile '+([...board.children].indexOf(tile)+1);open=[];},950);}}};});}}
document.querySelector('.skip').onclick = event => {
  event.preventDefault();
  main.focus();
  main.scrollIntoView();
};
window.addEventListener('hashchange',render);render();
